CREATE OR REPLACE FUNCTION public.ensure_account() RETURNS public.accounts LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_account public.accounts; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Login necessário'; END IF; INSERT INTO public.accounts(user_id) VALUES(auth.uid()) ON CONFLICT (user_id) DO NOTHING; SELECT * INTO v_account FROM public.accounts WHERE user_id = auth.uid(); RETURN v_account; END $$;